insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('89a0e232-cd09-431b-95cf-c13e160febc8', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$inleiding: kunst-alvleesklier op zakformaat getest door Rien$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context1.png$$,
   $$Een Nederlands bedrijf is erin geslaagd een kunst-alvleesklier te ontwikkelen op zakformaat. De 29-jarige Rien is een van de proefpersonen die de kunst-alvleesklier mag testen.$$, 'inline'),
  ('71ea7a69-cd23-40f5-a902-91f32a73ddb4', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$diabetes type 1; kunst-alvleesklier met glucose-sensor en pompjes voor insuline en glucagon (afbeelding 1)$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context2.png$$,
   $$afbeelding 1: foto van de kunst-alvleesklier op de buik van een patiënt
Rien heeft diabetes type 1. Door deze aandoening geeft zijn alvleesklier te weinig insuline af waardoor zijn lichaam het bloedsuikergehalte niet goed kan reguleren. De kunst-alvleesklier (afbeelding 1) heeft een glucose-sensor en twee pompjes die, afhankelijk van het bloedsuikergehalte, het hormoon insuline of het hormoon glucagon in de juiste dosis aan het bloed toedienen.$$, 'inline'),
  ('d55e2e84-7a39-452c-a58a-ea3eae84cc7c', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$insuline spuiten, hypers en hypo's; slap na sporten$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context3.png$$,
   $$Op 14-jarige leeftijd werd bij Rien diabetes type 1 geconstateerd. Vanaf dat moment moest hij vier keer per dag insuline gaan spuiten. Hij leerde om hypers (te hoge bloedsuikergehaltes) en hypo’s (te lage bloedsuikergehaltes) te vermijden door de hoeveelheid insuline die hij toediende, af te stemmen op de hoeveelheid koolhydraten die hij at. Ook moest hij rekening houden met zijn lichamelijke activiteit. Rien vertelt: “Ik moest vooral leren om bij sportactiviteiten niet te enthousiast van start te gaan. Anders voelde ik me na één uur al zo slap als een vaatdoek.”$$, 'inline'),
  ('c6f0b45d-24a7-4b8c-b76e-675dec4d27b7', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$verklaring met twee open plekken (1) en (2)$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context4.png$$,
   $$Voor het feit dat Rien zich na één uur sporten zo slap voelde, wordt de volgende verklaring gegeven: Door een sterke toename van de ...(1)… ontwikkelde Rien een …(2)…$$, 'inline'),
  ('c3f28b96-c466-4d3c-8ad4-c73e46068839', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$glucose-sensor niet op de poortader aangesloten$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context5.png$$,
   $$Toen bij Rien de kunst-alvleesklier werd aangebracht, is de glucose- sensor op een bloedvat in zijn buik aangesloten. Hierbij werd, om twee redenen, niet voor de poortader gekozen. Eén reden is de diepe ligging van de poortader.$$, 'inline'),
  ('a192e787-907e-4d8b-8407-fadaa3b52a31', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$voetbal, lunch en film; drie tijdstippen voor insulinetoediening$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context6.png$$,
   $$Rien gaat op zaterdag één uur na het ontbijt een voetbalwedstrijd spelen. Na de wedstrijd luncht hij. Meteen hierna kijkt hij naar een film. Zowel zijn ontbijt als lunch zijn koolhydraatrijke maaltijden. Drie tijdstippen waarop mogelijk insuline wordt toegediend, zijn:
1 een half uur na het ontbijt,
2 tijdens de tweede helft van de voetbalwedstrijd,
3 tijdens het filmkijken, na de lunch.$$, 'inline'),
  ('917524c0-e355-427e-abba-847dd2677759', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$glucagon wordt afgegeven in een ader in de buikwand; doelwitorgaan lever$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context7.png$$,
   $$Op een bepaald moment geeft de kunst-alvleesklier van Rien glucagon af in een ader in de buikwand. Dit hormoon heeft de lever als doelwitorgaan.$$, 'inline'),
  ('437bef75-ef8a-4483-9f5c-234646796a08', 'b01c8a58-f34b-456c-ad9a-c65e80806fd8', $$niet alle functies van de alvleesklier worden overgenomen$$,
   $$biologie-havo-2018-ii-kunst-alvleesklier-context8.png$$,
   $$Niet alle functies van de alvleesklier worden door de kunst-alvleesklier overgenomen.$$, 'inline'),
  ('ccfffd3e-f0a8-49f3-b216-cdd5d0624a4f', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$inleiding: overgang van vissen naar vierpotige landdieren$$,
   $$biologie-havo-2018-ii-levend-fossiel-context1.png$$,
   $$Tussen de 400 en 350 miljoen jaar geleden zijn er uit vissen vierpotige landdieren ontstaan. De overgang van water naar land was mogelijk dankzij een aantal ingrijpende aanpassingen.$$, 'inline'),
  ('04b3420b-8b17-4283-b1e8-eb03fa1e8471', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$fossielen vergelijken; longvis (afbeelding 1) en coelacanth (afbeelding 2) als kwastvinnigen$$,
   $$biologie-havo-2018-ii-levend-fossiel-context2.png$$,
   $$Om de evolutionaire ontwikkeling van deze aanpassingen te volgen worden fossielen vergeleken met nu nog levende organismen. Daarbij is het van belang te weten welke nu nog levende vissoort het meest verwant is aan de vissen die als eerste ‘vin aan wal’ zetten. Twee kwastvinnige vissoorten komen in aanmerking: de longvis (afbeelding 1) en de coelacanth (afbeelding 2). Met behulp van DNA-analyse hebben onderzoekers uitgezocht welke het meest verwant is.
afbeelding 1: foto van een longvis
afbeelding 2: foto van een coelacanth$$, 'inline'),
  ('dfc89bc3-72b7-4096-af2a-360c177e4911', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$coelacanth: leefwijze en nauwelijks veranderd in 70 miljoen jaar (afbeelding 3)$$,
   $$biologie-havo-2018-ii-levend-fossiel-context3.png$$,
   $$Coelacanthen hebben vinnen die aan pootjes doen denken, leven op grote diepte in grotten en hebben weinig predatoren. Voordat een Zuid-Afrikaanse visser in 1938 een coelacanth in zijn netten aantrof, dacht men dat deze vis al 70 miljoen jaar was uitgestorven omdat tot dan toe alleen fossielen van deze vis (afbeelding 3) gevonden waren. De exemplaren die nu leven, zijn nauwelijks verschillend van de coelacanthen van 70 miljoen jaar geleden.
afbeelding 3: foto van een fossiele coelacanth$$, 'inline'),
  ('569a4197-4443-47ef-bbd3-23fa82df25fe', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$specifieke nucleotidenvolgorde bij vierpotigen en kwastvinnigen$$,
   $$biologie-havo-2018-ii-levend-fossiel-context4.png$$,
   $$De transformatie van vinnen naar poten lijkt al vóór de overgang van water naar land te zijn ingezet. De pootachtige vinnen van de coelacanth wijzen hierop, maar ook op DNA-niveau zijn hiervoor aanwijzingen te vinden. De onderzoekers troffen een specifieke nucleotiden-volgorde aan die wel in alle vierpotige landdieren en kwastvinnigen voorkomt, maar niet in andere vissen.$$, 'inline'),
  ('440353d6-16cd-4bbf-8a92-57f25f77c013', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$nucleïnezuur uit weefsels van muizenembryo's geanalyseerd$$,
   $$biologie-havo-2018-ii-levend-fossiel-context5.png$$,
   $$Om de rol van dit stukje DNA te onderzoeken werd een nucleïnezuur uit verschillende weefsels van muizenembryo’s geanalyseerd. Hieruit bleek dat het stukje DNA vooral actief is in die delen waar de poten van de muis zich ontwikkelen.$$, 'inline'),
  ('cc0c83de-bebb-4912-9cff-d705f5be6dca', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$verwantschap van gewervelden bepaald met DNA-analyse$$,
   $$biologie-havo-2018-ii-levend-fossiel-context6.png$$,
   $$Om de meest recente voorouder van de gewervelde landdieren en kwastvinnigen te achterhalen, is met behulp van DNA-analyse de verwantschap van verschillende soorten gewervelden bepaald. Deze verwantschap is weergegeven in afbeelding 4.$$, 'inline'),
  ('486c9490-bb82-4d05-a466-81c453f37677', 'c5e35d1b-2ee8-4784-ac7d-f629b8886a39', $$afbeelding 4: evolutionaire stamboom van gewervelden$$,
   $$biologie-havo-2018-ii-levend-fossiel-context7.png$$,
   $$afbeelding 4: evolutionaire stamboom (tijdas 400 – 0 miljoen jaar geleden) met de soorten mens, olifant, wallaby, vogelbekdier, vink, kraaghagedis, bruine kikker, longvis, coelacanth, zebravis en hondshaai. De longvis splitst zich later af van de tak van de landdieren dan de coelacanth.$$, 'inline'),
  ('eac20f28-b241-45ea-998d-5e6860641aa5', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$inleiding: baby Stan met de erfelijke stofwisselingsziekte MSUD$$,
   $$biologie-havo-2018-ii-msud-context1.png$$,
   $$Maud werkt als diëtiste in een academisch ziekenhuis. Een van haar patiëntjes is Stan, een baby met de zeldzame erfelijke stofwisselingsziekte MSUD. Met de ouders bespreekt zij een aangepast dieet voor Stan.$$, 'inline'),
  ('f7329220-572d-4f18-8692-2673898d2c65', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$MSUD: enzym breekt aminozuren leucine, isoleucine en valine niet af$$,
   $$biologie-havo-2018-ii-msud-context2.png$$,
   $$Kenmerkend voor MSUD (maple syrup urine disease) is een zoetige geur van de urine. Deze geur doet denken aan esdoornsiroop (maple syrup). Bij patiënten met MSUD werkt een bepaald enzym niet goed waardoor ze de aminozuren leucine, isoleucine en valine niet kunnen afbreken. Hierdoor ontstaat een te hoge concentratie van deze aminozuren in het bloed. Dit leidt ertoe dat MSUD, indien onbehandeld, hersenschade kan veroorzaken.$$, 'inline'),
  ('0652f53b-67df-4cdb-b037-7f0d4074fac0', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$afbraak van aminozuren in de lever levert een afvalproduct$$,
   $$biologie-havo-2018-ii-msud-context3.png$$,
   $$Een belangrijk orgaan bij de afbraak van aminozuren is de lever. Bij de afbraak van aminozuren ontstaat een afvalproduct dat wordt uitgescheiden.$$, 'inline'),
  ('9a1a7fd8-9225-46c3-a2e3-5cb8e08021ee', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$MSUD ontdekt met de hielprik; concentratie aminozuren in het bloed$$,
   $$biologie-havo-2018-ii-msud-context4.png$$,
   $$Bij Stan werd MSUD ontdekt dankzij de hielprik. De hielprik vindt enkele dagen na de geboorte plaats. Er wordt bloed afgenomen dat onderzocht wordt om verschillende aangeboren aandoeningen op te sporen. Om te bepalen of een baby MSUD heeft, wordt de concentratie van verschillende aminozuren bepaald.$$, 'inline'),
  ('faebc7ab-a8d4-4c29-80d5-c536cb4ea4be', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$dieetadvies: beperking van één hoofdgroep voedingsstoffen$$,
   $$biologie-havo-2018-ii-msud-context5.png$$,
   $$Om te voorkomen dat Stan klachten krijgt, schrijft Maud een voedingssupplement voor en geeft ze Stans ouders een dieetadvies voor Stan. Dit advies betreft de beperking van de inname van één van de hoofdgroepen van voedingstoffen: eiwitten, koolhydraten, vetten, mineralen of vitaminen.$$, 'inline'),
  ('9028db50-e49f-4515-b887-c79c5a097a5f', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$familieonderzoek naar MSUD; uitslagen in de stamboom$$,
   $$biologie-havo-2018-ii-msud-context6.png$$,
   $$Voor een uitgebreid onderzoek naar MSUD in de familie van Stan werd bij familieleden wangslijmvlies afgenomen en onderzocht. In de stamboom van de familie (afbeelding 1) zijn de uitslagen aangegeven.$$, 'inline'),
  ('86e9b564-072a-48eb-94ca-e618993b3db4', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$afbeelding 1: stamboom van de familie van Stan$$,
   $$biologie-havo-2018-ii-msud-context7.png$$,
   $$afbeelding 1: stamboom van de familie van Stan.
Generatie I: 1 (vrouw) × 2 (man); 3 (vrouw) × 4* (man).
Generatie II: 1 (vrouw) en 2* (vrouw) zijn kinderen van I-1 en I-2; 3* (man) en 4 (vrouw) zijn kinderen van I-3 en I-4. II-2* en II-3* zijn de ouders van Stan.
Generatie III: Stan (man, MSUD).
Legenda: open symbool = geen MSUD, grijs symbool = MSUD; * bij deze personen is een afwijkend allel aangetroffen.$$, 'inline'),
  ('b99b99ed-5125-40ed-a1d2-d90d7741f9c8', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$kans dat een volgend kind ook MSUD heeft$$,
   $$biologie-havo-2018-ii-msud-context8.png$$,
   $$De ouders van Stan vragen zich af wat de kans is dat een volgend kind ook MSUD heeft.$$, 'inline'),
  ('0bc482d9-a320-4afb-8712-7670fd99e8e2', '7d4f6274-3418-40e0-9936-4f70d36b5bc2', $$mutatie bij Stans moeder; vier cellen waarin de mutatie kan zijn opgetreden$$,
   $$biologie-havo-2018-ii-msud-context9.png$$,
   $$Bij de ouders van Stans moeder (I-1 en I-2, afbeelding 1) werd het afwijkende allel niet aangetroffen. Dit betekent dat er één mutatie opgetreden is die heeft geleid tot het afwijkende allel bij Stans moeder. Vier cellen zijn:
1 een eicel van oma I-1,
2 een zaadcel van opa I-2,
3 de bevruchte eicel waaruit Stans moeder (II-2) is ontstaan,
4 een eicel van Stans moeder (II-2).$$, 'inline'),
  ('b41d90e5-4939-428b-a117-801e271a5cad', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$inleiding: muizenplaag op het Friese platteland$$,
   $$biologie-havo-2018-ii-muizenplaag-context1.png$$,
   $$In de winter van 2015 werd het Friese platteland geteisterd door een muizenplaag. Veel melkveeboeren hadden een grote schadepost doordat de muizen hun weilanden ruïneerden. Wietse en Jelte onderzoeken de biologische aspecten van deze muizenplaag.$$, 'inline'),
  ('9946ed9a-23fd-4ca5-8b40-a86e14c13ec3', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$veldmuis (afbeelding 1) eet graswortels; zetmeel, glucose en vitamine C$$,
   $$biologie-havo-2018-ii-muizenplaag-context2.png$$,
   $$De muis die de plaag veroorzaakte, was de veldmuis (Microtus arvalis, afbeelding 1). De veldmuizen graven gangen en eten graswortels waardoor het gras verdroogt. Wietse en Jelte denken dat in de wortels van gras koolhydraten worden opgeslagen in de vorm van zetmeel, dat goed door veldmuizen te verteren is. Daarnaast vragen ze zich af of graswortels glucose en vitamine C bevatten.
afbeelding 1: foto van een veldmuis$$, 'inline'),
  ('38a11d93-dc01-4b25-8eee-0cae7a77921d', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$suikers worden van de grassprieten naar de wortels getransporteerd$$,
   $$biologie-havo-2018-ii-muizenplaag-context3.png$$,
   $$Voor de opbouw van zetmeel worden suikers gebruikt. Suikers worden vanuit de grassprieten naar de wortels getransporteerd.$$, 'inline'),
  ('b8e2bb87-0d40-447a-902c-3fe4c5ea4c16', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$koolhydraten in de wortel als reservevoedsel en gebruikt$$,
   $$biologie-havo-2018-ii-muizenplaag-context4.png$$,
   $$In de wortel wordt een gedeelte van de koolhydraten als reservevoedsel opgeslagen, en een gedeelte wordt gebruikt.$$, 'inline'),
  ('bc7adf75-4784-4f23-b699-3775aeefa0f3', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$experiment met sap van graswortels en indicatorreacties$$,
   $$biologie-havo-2018-ii-muizenplaag-context5.png$$,
   $$Om te onderzoeken welke voedingstoffen in graswortels aanwezig zijn, voeren Wietse en Jelte het volgende experiment uit. Ze verzamelen 10 gram graswortels en persen die uit. Het op die manier verkregen sap vullen ze aan met water tot 15 mL. Ze gebruiken standaard-indicatorreacties om voedingstoffen aan te tonen. Tabel 1 geeft de kleuromslag aan van de indicatorreactie.$$, 'inline'),
  ('903802ac-8827-4f50-aa79-37ee4ebcc7c0', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$tabel 1: indicatoren met voedingsstof en kleuromslag$$,
   $$biologie-havo-2018-ii-muizenplaag-context6.png$$,
   $$tabel 1 (indicator – voedingsstof – kleuromslag)
Fehlings-reagens – glucose – blauw → oranje
joodoplossing – zetmeel – bruingeel → blauw
DCPIP – vitamine C – blauw → kleurloos$$, 'inline'),
  ('ea116965-b56d-4b0b-9c8a-f99877fd1947', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$drie buizen met verdund graswortelsap$$,
   $$biologie-havo-2018-ii-muizenplaag-context7.png$$,
   $$Wietse en Jelte vullen drie genummerde buizen elk met 5 mL van het verdunde graswortelsap en onderzoeken buis 1 met Fehlings-reagens, buis 2 met joodoplossing en buis 3 met DCPIP. In tabel 2 staan hun resultaten.$$, 'inline'),
  ('757418d0-de9a-4d04-a78d-e4967df77d77', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$tabel 2: resultaten van de drie buizen$$,
   $$biologie-havo-2018-ii-muizenplaag-context8.png$$,
   $$tabel 2 (buis – toegevoegde indicator – kleur)
1 – Fehlings-reagens – oranje
2 – joodoplossing – blauw
3 – DCPIP – blauw$$, 'inline'),
  ('c8b80f33-a480-4380-a2d7-ffad716e1623', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$vertering van zetmeel tot monosachariden door verschillende enzymen$$,
   $$biologie-havo-2018-ii-muizenplaag-context9.png$$,
   $$De veldmuizen moeten het zetmeel uit de wortels eerst verteren. De koolhydraatvertering vindt bij de muis op dezelfde manier plaats als bij de mens. Bij vertering van zetmeel tot monosachariden zijn verschillende enzymen betrokken.$$, 'inline'),
  ('6d9897c4-438e-41d7-8db0-2166248a1014', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$snelle voortplanting van veldmuizen; plaag eens in de drie jaar$$,
   $$biologie-havo-2018-ii-muizenplaag-context10.png$$,
   $$Een paartje veldmuizen kan een aantal maal per jaar een nest van ongeveer vijf jonkies krijgen. Onder gunstige omstandigheden kan de populatie daardoor elke drie maanden drie keer zo groot worden. Deze snelle voortplanting zorgt ervoor dat eens in de drie jaar de populatie tot plaaggrootte uitgroeit. Gewoonlijk sterft hierna een groot deel van de populatie en begint de cyclus opnieuw.$$, 'inline'),
  ('1f4346f5-2a67-418d-b6a9-4b94f48813c9', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$berekening van de populatiegroei vanaf 100 veldmuizen$$,
   $$biologie-havo-2018-ii-muizenplaag-context11.png$$,
   $$Met deze gegevens berekenen Wietse en Jelte hoe een populatie van 100 veldmuizen gedurende drie jaar in aantal kan toenemen. Ze gaan er in hun berekening van uit dat tijdens de gehele periode de omstandigheden gunstig zijn. Ze geven hun resultaten in een diagram weer. Hieronder zijn twee diagrammen weergegeven:$$, 'inline'),
  ('03cfa369-69b1-4364-bcda-864cdbb1fba3', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$diagram 1 en diagram 2: populatiegrootte tegen tijd$$,
   $$biologie-havo-2018-ii-muizenplaag-context12.png$$,
   $$diagram 1: populatiegrootte (aantal veldmuizen) tegen tijd (0-36 maanden): de lijn stijgt eerst snel en vlakt daarna af (S-vormig, verzadigend).
diagram 2: populatiegrootte (aantal veldmuizen) tegen tijd (0-36 maanden): de lijn blijft eerst laag en stijgt daarna steeds sneller (exponentieel).$$, 'inline'),
  ('81755e79-7586-4358-a213-152aaf832ad8', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$Google Earth-foto van het gebied: vooral grasland$$,
   $$biologie-havo-2018-ii-muizenplaag-context13.png$$,
   $$Wietse en Jelte bekijken het gebied waar de plaag heerst, op Google Earth. De foto is genomen vóór de muizenplaag toen het gras nog groen was. Ze zien dat het grootste gedeelte van het gebied bestaat uit grasland (afbeelding 2).$$, 'inline'),
  ('726eaac0-9d4b-4a3d-b7a7-f77356c8480e', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$afbeelding 2: luchtfoto van het gebied$$,
   $$biologie-havo-2018-ii-muizenplaag-context14.png$$,
   $$afbeelding 2: luchtfoto (Google Earth) van het gebied, grotendeels bestaand uit graslanden met sloten$$, 'inline'),
  ('8d2cc36e-06b8-4286-a9ef-f222268a6674', '72e209c5-c6b0-4145-9d8a-943036f9123d', $$afwisselende begroeiing tussen de weilanden$$,
   $$biologie-havo-2018-ii-muizenplaag-context15.png$$,
   $$Wietse en Jelte bedenken dat het voor het onder controle houden van de muizenpopulatie verstandig zou zijn om afwisselende begroeiing aan te brengen tussen de weilanden.$$, 'inline'),
  ('b8281730-2847-488d-aa74-57308a5390d8', '48398b3b-ab60-4068-8677-d04377f152cb', $$inleiding: stoffen van de sluipwesp voor de ontwikkeling van de larve$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context1.png$$,
   $$Een sluipwesp produceert verschillende stoffen die ertoe leiden dat een sluipwesplarve zich ongestoord kan ontwikkelen in het lichaam van een gastheer.$$, 'inline'),
  ('266ba877-077c-4f74-a579-e272fdb98f8f', '48398b3b-ab60-4068-8677-d04377f152cb', $$smaragdsluipwesp en Amerikaanse kakkerlak (afbeelding 1); relatie niet parasitair, geen predatie$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context2.png$$,
   $$De smaragdsluipwesp Ampulex compressa (afbeelding 1, rechts), injecteert een gif in het zenuwstelsel van een Amerikaanse kakkerlak Periplaneta americana (afbeelding 1, links). Dit milde gif, een neurotoxine, verdooft de kakkerlak, waardoor geen vluchtreactie optreedt. Vervolgens trekt de sluipwesp de kakkerlak aan zijn voelspriet mee naar zijn hol.
afbeelding 1: foto van een smaragdsluipwesp met een kakkerlak
In het hol zet de sluipwesp een ei af op de buikzijde van het slachtoffer. De larve die zich hieruit ontwikkelt, leeft eerst op en daarna in de kakkerlak en voedt zich met lichaamsvloeistof en organen van de kakkerlak. Zelf is de kakkerlak niet meer in staat te eten en sterft.
De relatie tussen de larve van de smaragdsluipwesp en de Amerikaanse kakkerlak is niet parasitair omdat de gastheer niet in leven blijft. Toch is er geen sprake van predatie.$$, 'inline'),
  ('ec161ae5-a47f-40cb-8a2a-08c06581fd69', '48398b3b-ab60-4068-8677-d04377f152cb', $$neurotoxine blokkeert receptoren voor neurotransmitters; schakeling met plaatsen P, Q en R$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context3.png$$,
   $$Het neurotoxine dat de smaragdwesp inspuit, blokkeert de receptoren voor bepaalde neurotransmitters in het zenuwstelsel van de kakkerlak. Afbeelding 2 geeft een schakeling weer van zenuwcellen bij insecten. De pijlen geven de richting van de impulsen aan. Zenuwcel B is een schakelzenuwcel. Drie plaatsen op de zenuwcellen zijn met de letters P, Q en R aangegeven.$$, 'inline'),
  ('a1ca89da-96ee-4f1d-bfe9-7ea808c22b1f', '48398b3b-ab60-4068-8677-d04377f152cb', $$afbeelding 2: schakeling van zenuwcellen bij insecten$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context4.png$$,
   $$afbeelding 2: schakeling van zenuwcellen: zenuwcel A geleidt een impuls (pijl, plaats P) naar een synaps (Q aan de kant van cel A, R aan de kant van cel B); cel B (schakelzenuwcel) geleidt de impuls verder (pijl naar rechts).$$, 'inline'),
  ('f5be3a50-0898-4824-880e-0322017a8087', '48398b3b-ab60-4068-8677-d04377f152cb', $$gewicht organische stoffen na de metamorfose van de sluipwesplarve$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context5.png$$,
   $$Uit één volwassen kakkerlak komt na de metamorfose van de sluipwesplarve één volwassen sluipwesp. Van de kakkerlak blijft alleen het chitinepantser over. Na het uitkomen van de sluipwesp wordt het totaalgewicht aan organische stoffen van het chitinepantser van de kakkerlak en van het lichaam van de volwassen sluipwesp bepaald. 2p 23 − Is dit gezamenlijk gewicht groter dan, gelijk aan of kleiner dan het$$, 'inline'),
  ('e81412c8-31f9-4166-85a9-9394176becde', '48398b3b-ab60-4068-8677-d04377f152cb', $$larve spuugt een mengsel van antibiotica in de kakkerlak$$,
   $$biologie-havo-2018-ii-sluipwesp-verdooft-en-ontsmet-context6.png$$,
   $$Een kakkerlak die doodgaat, wordt normaal al snel door bacteriën opgeruimd. Om dit bederf van zijn voedsel te voorkomen, spuugt de larve van de sluipwesp een vloeistof met een bacteriedodende werking in het lichaam van de kakkerlak. De vloeistof bevat een mengsel van verschillende antibiotica. Zo’n mengsel heeft als voordeel boven een enkel antibioticum dat bacteriën niet snel resistent worden.$$, 'inline'),
  ('ad65e8af-3f6a-4fa0-8c6f-c57954cc980e', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$inleiding: optometrist onderzoekt patiënten met macula-degeneratie$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context1.png$$,
   $$Tijdens haar hbo-studie optometrie loopt Floor stage bij een optometrist. De optometrist onderzoekt twee patiënten met leeftijdgebonden macula- degeneratie.$$, 'inline'),
  ('edbad125-22a8-44bc-9d62-4800ae8e4754', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$LMD: eiwitophoping achter het netvlies; Amsler-test (afbeelding 1a en 1b)$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context2.png$$,
   $$Bij mensen met macula-degeneratie (LMD) raakt het netvlies vervormd doordat eiwitten zich ophopen achter het netvlies of doordat daar extra bloedvaatjes ontstaan. Deze veranderingen veroorzaken een afwijkend beeld. Dit wordt duidelijk via de Amsler-test. Hierbij kijken patiënten naar een raster (afbeelding 1a). Als ze hierin vervormingen waarnemen, zoals in afbeelding 1b, is er mogelijk sprake van LMD.
afbeelding 1a: recht raster (normaal beeld)
afbeelding 1b: raster met vervormde lijnen in het midden (afwijkend beeld)$$, 'inline'),
  ('6e6c97d2-2178-450e-96e6-4be51f2dd24c', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$atropine ontspant kringspieren in het oog; pupil groot, niet scherp zien$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context3.png$$,
   $$De optometrist bestudeert het netvlies van een patiënt die kleine vervormingen van zijn beeld waarneemt. Hiervoor druppelt de optometrist atropine in het oog, waardoor alle kringspieren in het oog zich ontspannen en de pupil groot wordt. Hij heeft dan via de pupil goed zicht op het netvlies. Een bijwerking van deze oogdruppels is dat de patiënt tijdelijk niet scherp ziet.$$, 'inline'),
  ('4bb8ddf2-1308-4820-a3ea-5b5872a88eee', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$vergevorderde LMD: zintuigcellen verdwenen$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context4.png$$,
   $$Een andere patiënt heeft LMD in een vergevorderd stadium. Op de plekken waar de ophopingen zijn ontstaan, zijn de zintuigcellen zelfs verdwenen. De patiënt legt aan Floor uit wat hij ziet:$$, 'inline'),
  ('af053d0b-2826-4c2c-9742-ed0ff2bd7ad1', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$patiënt beschrijft wat hij ziet$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context5.png$$,
   $$“Als ik je in de ogen probeer te kijken, dan zie ik helemaal niets. Geen scheve ogen, geen rare ogen, maar géén ogen. Ook geen zwarte of grijze vlekken; niets op de plek waar ik ogen zou willen zien. Maar als ik naar je voorhoofd kijk, zo ongeveer bij de haargrens, dán zie ik ineens je ogen!”$$, 'inline'),
  ('af149a59-ebf0-463d-923a-de5593b05b49', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$onderzoek met zink en antioxidanten in vier groepen$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context6.png$$,
   $$Floor leest dat het extra innemen van zink en antioxidanten de voortgang van LMD kan vertragen bij patiënten met een beginstadium van LMD. De werkzaamheid van deze supplementen is bepaald in een Amerikaans onderzoek. Voor dit onderzoek zijn ruim 4500 patiënten met een beginstadium van LMD in vier groepen verdeeld die elk een verschillende behandeling kregen:
− Groep 1 was de controlegroep.
− Groep 2 kreeg pillen met zink.
− Groep 3 kreeg pillen met antioxidanten.
− Groep 4 kreeg pillen met zink en antioxidanten.$$, 'inline'),
  ('49c8f382-323e-47c9-8e2a-d6a0e6f07c5f', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$tien jaar lang gezichtsvermogen gemeten$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context7.png$$,
   $$In het Amerikaanse onderzoek werd gedurende tien jaar bij de patiënten jaarlijks het gezichtsvermogen gemeten. De resultaten van dit onderzoek zijn in een grafiek weergegeven (afbeelding 2).$$, 'inline'),
  ('5e55df6d-4e26-4712-b609-4e7e08d61ece', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$afbeelding 2: kans op matig verlies aan gezichtsvermogen per groep$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context8.png$$,
   $$afbeelding 2: lijngrafiek van de kans op matig verlies aan gezichtsvermogen (in procenten, 0-60) tegen de tijd in jaren (0-10) voor groep 1 (controle), groep 2 (zink), groep 3 (antioxidanten) en groep 4 (zink + antioxidanten). Alle lijnen stijgen; na 10 jaar ligt groep 1 het hoogst (ruim 50%), groep 4 het laagst (ongeveer 45%) en groepen 2 en 3 daartussen (rond 49%).$$, 'inline'),
  ('064b0c3d-7529-411c-a0bb-31896cc4c189', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$drie conclusies van Floor$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context9.png$$,
   $$Naar aanleiding van deze gegevens trekt Floor drie conclusies.
1 Behandeling met zink en antioxidanten samen leidt tot een minder grote kans op matig verlies aan gezichtsvermogen dan behandeling met alleen zink.
2 Bij behandeling met alleen zink is na tien jaar het gezichtsvermogen met 50% afgenomen.
3 Na twintig jaar is de kans dat onbehandelde patiënten niets meer zien 100%.$$, 'inline'),
  ('a6e19585-567e-4f98-806f-a853c8e18da7', 'bc067ba6-0f25-456d-aaf6-6f693bce6932', $$tweelingonderzoek naar de erfelijke component van LMD$$,
   $$biologie-havo-2018-ii-degeneratie-van-het-netvlies-context10.png$$,
   $$Als LMD in de familie voorkomt, is de kans op het krijgen van deze afwijking hoger. Floor bedenkt een onderzoek waarmee ze zou kunnen achterhalen hoe groot deze erfelijke component is. Hiervoor zou ze gegevens willen bestuderen van tweelingen van wie ten minste één van de twee LMD heeft. De tweelingen kan ze verdelen in vier categorieën:
1 eeneiig; beide individuen lijden aan LMD
2 eeneiig; slechts één van de twee lijdt aan LMD
3 twee-eiig; beide individuen lijden aan LMD
4 twee-eiig; slechts één van de twee lijdt aan LMD Ga ervan uit dat ze 100 tweelingparen onderzoekt van wie ten minste één van de twee LMD heeft. 50 paren hiervan zijn eeneiig, 50 paren twee-eiig. Als de aandoening inderdaad voornamelijk erfelijk bepaald is, zullen er meer tweelingparen in de ene categorie zitten dan in andere categorieën.$$, 'inline'),
  ('ee50d3ac-7d5f-4a10-9a02-de04cabf07dc', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$inleiding: rode Amerikaanse rivierkreeft (afbeelding 1) als exoot$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context1.png$$,
   $$De rode Amerikaanse rivierkreeft (afbeelding 1) is mogelijk medeverantwoordelijk voor het verdwijnen van de inheemse Europese rivierkreeft. Arjen de Groot van Wageningen University & Research doet onderzoek naar de opmars van deze exoot.
afbeelding 1: foto van een rode Amerikaanse rivierkreeft$$, 'inline'),
  ('2e27da42-5668-4e18-8e04-407f2b699044', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$tabel 1: in Nederland voorkomende rivierkreeften met wetenschappelijke naam$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context2.png$$,
   $$Rivierkreeften zijn geleedpotigen die leven in riviertjes, sloten en plassen. In tabel 1 staat een overzicht van de in Nederland voorkomende rivierkreeften.
tabel 1 (Nederlandse naam – wetenschappelijke naam – eerste vondst in Nederland)
Europese rivierkreeft – Astacus astacus – inheems
gevlekte Amerikaanse rivierkreeft – Orconectes limosus – 1968
Turkse rivierkreeft – Astacus leptodactylus – 1977
rode Amerikaanse rivierkreeft – Procambarus clarkii – 1985
gestreepte Amerikaanse rivierkreeft – Procambarus acutus – 2002
Californische rivierkreeft – Pacifastacus leniusculus – 2004
geknobbelde Amerikaanse rivierkreeft – Orconectes virilis – 2004$$, 'inline'),
  ('750647fb-f5b8-434f-8264-cf943ea4b629', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$Amerikaanse rivierkreeften verspreiden de kreeftenpest (schimmel)$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context3.png$$,
   $$De Amerikaanse rivierkreeften zijn door de mens in Nederland geïntroduceerd en ze verspreiden zich snel. Vooral het verspreidingsgebied van de rode Amerikaanse rivierkreeft neemt toe. De Europese rivierkreeft neemt ondertussen sterk in aantal af. Een belangrijke oorzaak voor het dreigende uitsterven van deze inheemse kreeft is de kreeftenpest. Deze zeer besmettelijke en dodelijke infectieziekte wordt veroorzaakt door een schimmel. De meeste Amerikaanse rivierkreeften zijn geïnfecteerd met deze schimmel, maar worden er niet ziek van. Ze kunnen de schimmel wel verspreiden.$$, 'inline'),
  ('cacc4dd0-5966-4910-a851-2afa6135356f', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$ziekteverschijnselen van de kreeftenpest$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context4.png$$,
   $$De ziekteverschijnselen van de kreeftenpest zijn: zeer onrustig gedrag en omvallen. Daarnaast wordt een zieke kreeft overdag actief in plaats van ’s nachts. Negen tot vijftien dagen na infectie sterft het dier.$$, 'inline'),
  ('7d488ad0-4d4b-41ea-bfcb-28ef209fc39c', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$aangeboren afweer bij geleedpotigen; vier processen$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context5.png$$,
   $$Bij geleedpotigen ontbreekt een verworven (specifiek) immuunsysteem. Geleedpotigen hebben wel een aangeboren (a-specifiek) afweersysteem, met dezelfde kenmerken als het menselijk aangeboren afweersysteem. Vier processen die een rol spelen bij de afweer, zijn:
1 fagocytose,
2 onderscheid maken tussen lichaamsvreemd en lichaamseigen,
3 productie van antistoffen,
4 productie van lysozymen.$$, 'inline'),
  ('7e3c5b68-9b27-4719-b4d0-72f9bf694f12', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$geïsoleerde populatie Europese rivierkreeften; kweekprogramma$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context6.png$$,
   $$De enige plek in Nederland waar de Europese rivierkreeft nog voorkomt, is een vijver op een landgoed bij Arnhem. Hier leeft een geïsoleerde populatie van enkele honderden individuen. Om het aantal inheemse kreeften te vergroten is een kweekprogramma opgezet. Er wordt een klein aantal ei-dragende vrouwtjes uit de bedreigde populatie weggevangen. Hierna worden de jongen in aquaria opgekweekt. Als deze volwassen zijn, worden ze uitgezet op zorgvuldig geselecteerde plaatsen.$$, 'inline'),
  ('cbb669bf-2673-4528-8e7a-ad8ec82e882c', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$allelfrequenties van nieuwe populaties wijken sterk af$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context7.png$$,
   $$Omdat er maar een klein aantal vrouwtjes wordt gebruikt voor het kweekprogramma, kunnen de allelfrequenties van de nieuwe populaties sterk gaan afwijken van die van de oorspronkelijke populatie.$$, 'inline'),
  ('92875602-5d18-4357-a58f-43f1ba120ea8', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$uitzetten van een kleine populatie; genetische variatie en overlevingskans$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context8.png$$,
   $$Het uitzetten van deze nieuwe, kleine populatie Europese rivierkreeften in een ander gebied is niet bij voorbaat een succes. Als de genetische variatie van deze populatie klein is, is de overlevingskans kleiner dan bij een populatie met een grote genetische variatie.$$, 'inline'),
  ('acb6f8bb-1f7b-419d-a2ea-b20a65a6db85', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$eDNA-onderzoek met watermonsters (afbeelding 2); merker voor de rode Amerikaanse rivierkreeft$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context9.png$$,
   $$Arjen de Groot maakt voor het onderzoek naar de verspreiding van de Amerikaanse rivierkreeften gebruik van zogenaamd eDNA (environmental DNA). Dit is DNA dat in het water terechtkomt via organische resten van organismen zoals huidcellen, haren, schubben, slijm of urine. Na het nemen van watermonsters (afbeelding 2) wordt het eDNA geanalyseerd.
afbeelding 2: foto van het nemen van een watermonster
De rode Amerikaanse rivierkreeft wordt geïdentificeerd aan de hand van een merker: een klein stukje kenmerkend DNA. Als de merker in een watermonster voorkomt, betekent dit dat de rode Amerikaanse rivierkreeft aanwezig is in het water waarvan het monster is genomen.$$, 'inline'),
  ('a8e06d41-e53e-406c-9f9f-f7c959b75918', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$merkers van de rode Amerikaanse rivierkreeft aangetroffen in een sloot$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context10.png$$,
   $$Bij eDNA-onderzoek van een sloot worden merkers van de rode Amerikaanse rivierkreeft aangetroffen.$$, 'inline'),
  ('50991780-69c4-4692-9191-8a178c8fbc41', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$traditionele methoden versus eDNA-techniek$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context11.png$$,
   $$Voordat eDNA gebruikt werd, werd de aanwezigheid van een soort met traditionele methoden bepaald. Voorbeelden hiervan zijn het waarnemen van sporen zoals keutels of pootafdrukken, of het vangen met een net of val. In afbeelding 3 wordt de detectiekans met de eDNA-techniek vergeleken met de detectiekans met traditionele methoden.$$, 'inline'),
  ('a62fab6f-6ce9-4265-bca6-1d383ec94eb8', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$afbeelding 3: detectiekans tegen dichtheid van de doelsoort$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context12.png$$,
   $$afbeelding 3: detectiekans (in procenten, 0-100) tegen de dichtheid van de doelsoort (laag → hoog) voor de eDNA-techniek (stippellijn) en traditionele methoden (doorgetrokken lijn). Beide stijgen S-vormig naar 100%; de eDNA-lijn ligt bij lage dichtheden hoger en stijgt eerder.$$, 'inline'),
  ('c21d0c67-6c0c-47dd-8ae5-bad2d14fa5d9', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$eDNA gebruiken om uitzetgebieden zonder Amerikaanse rivierkreeften te vinden$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context13.png$$,
   $$Om zeker te weten dat Europese rivierkreeften worden uitgezet in een gebied zonder Amerikaanse rivierkreeften, kan de eDNA-techniek worden ingezet.$$, 'inline'),
  ('f3222f3b-af82-4aef-9bc5-e1b68fb96767', '3b502f98-d5a5-4c2f-9777-6f873773b991', $$in België verbinden nieuwe sloten geïsoleerde waterecosystemen$$,
   $$biologie-havo-2018-ii-amerikaanse-invasie-in-nederlandse-sloten-context14.png$$,
   $$Ook in België worden geïsoleerde populaties Europese rivierkreeften bedreigd door de aanwezigheid van Amerikaanse rivierkreeften. Net zoals in Nederland is gebeurd, worden in België kleine waterecosystemen met elkaar verbonden via nieuw gegraven sloten of door het verleggen van beken.$$, 'inline'),
  ('70ac97f4-bff3-4601-b0c0-6030f859ec09', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$inleiding: reuzenpanda eet bamboe (afbeelding 1); cellulase van darmbacteriën$$,
   $$biologie-havo-2018-ii-pandakeutels-context1.png$$,
   $$afbeelding 1: foto van een reuzenpanda die bamboe eet
Reuzenpanda’s zijn het grootste deel van de dag bezig met het eten van bamboe (afbeelding 1). Deze eigenschap bracht wetenschappers op het idee darmbacteriën van reuzenpanda’s te gebruiken bij de productie van biobrandstoffen.
De reuzenpanda kan leven op een dieet van uitsluitend bamboe dankzij de cellulase die zijn darmbacteriën produceren.$$, 'inline'),
  ('64282fba-7f33-44e3-b0f9-ff53766494c3', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$T1R1-gen voor de umami-receptor is veranderd bij de reuzenpanda$$,
   $$biologie-havo-2018-ii-pandakeutels-context2.png$$,
   $$In tegenstelling tot andere beren houden reuzenpanda’s niet van vlees. Het gen dat vlees hartig laat smaken (het T1R1-gen), is bij de reuzenpanda veranderd. Hierdoor heeft vlees voor reuzenpanda’s geen aantrekkelijke smaak. Het T1R1-gen codeert voor een receptor die vlees hartig doet smaken: de umami-receptor.$$, 'inline'),
  ('96ff674c-3565-4b38-acdc-6767956ba388', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$mutatie van het T1R1-gen geeft niet-werkzame umami-receptoren$$,
   $$biologie-havo-2018-ii-pandakeutels-context3.png$$,
   $$Bij de reuzenpanda is een mutatie van het T1R1-gen verantwoordelijk voor niet-werkzame umami-receptoren.$$, 'inline'),
  ('bba45503-2656-4972-a6cb-dcd28e8e7fe6', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$tweede-generatie-biobrandstoffen uit plantenresten$$,
   $$biologie-havo-2018-ii-pandakeutels-context4.png$$,
   $$De darmbacteriën van de reuzenpanda staan sterk in de belangstelling van wetenschappers die onderzoek doen naar de productie van tweede- generatie-biobrandstoffen. Tweede-generatie-biobrandstoffen worden verkregen uit plantenresten die overblijven na het oogsten van gewassen.$$, 'inline'),
  ('e062c251-c736-480e-8166-26e80e4ac9c9', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$eerste-generatie-biobrandstoffen uit maïs of suikerriet$$,
   $$biologie-havo-2018-ii-pandakeutels-context5.png$$,
   $$Eerste-generatie-biobrandstoffen worden gemaakt uit maïs of suikerriet.$$, 'inline'),
  ('ffdb53da-3608-4868-9364-69ac3a9ee7a0', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$genen voor cellulose-afbrekende enzymen in gist; bioreactor (afbeelding 2)$$,
   $$biologie-havo-2018-ii-pandakeutels-context6.png$$,
   $$afbeelding 2: foto van een bioreactor
De darmbacteriën van de reuzenpanda zijn in staat om heel efficiënt cellulose af te breken tot enkelvoudige suikers. Door genen van deze bacteriën in te bouwen in gistcellen zouden de enzymen die cellulose afbreken, op grote schaal geproduceerd kunnen worden. De gemodificeerde gist wordt dan in een bioreactor vermeerderd en aangezet tot productie van de gewenste enzymen (afbeelding 2). Deze enzymen worden gebruikt voor de productie van tweede-generatie-biobrandstoffen.$$, 'inline'),
  ('b236bbfb-215e-4ebf-b992-d899bf92fbcc', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$ideale abiotische omstandigheden in de bioreactor$$,
   $$biologie-havo-2018-ii-pandakeutels-context7.png$$,
   $$Voor een optimale productie van enzymen door gist moeten de ideale abiotische omstandigheden worden gecreëerd in de bioreactor.$$, 'inline'),
  ('e9373cfa-0c4e-4b19-bfa5-6f7b776e843a', 'c4f67f27-1eb7-4eb6-ade3-92b943bfe675', $$biobrandstoffen als oplossing voor het versterkt broeikaseffect$$,
   $$biologie-havo-2018-ii-pandakeutels-context8.png$$,
   $$De tweede-generatie-biobrandstoffen moeten een oplossing bieden voor het versterkt broeikaseffect, dat veroorzaakt wordt door het gebruik van fossiele brandstoffen.$$, 'inline');

